/// <summary>
/// CB201_RebatesExtension_GSTchanges
/// MET Follow trans item gst group on modified
/// </summary>
/// <param name="sender"> Get form data scontrol object</param>
/// <param name="e">Get form control event args</param>
[FormControlEventHandler(formControlStr(TAMRebatePosting, METFollowTransItemGSTGroup), FormControlEventType::Modified),
 SuppressBPWarningAttribute("BPParameterNotUsed", "@MET:BPParameterNotUsedMessage")]
public static void METFollowTransItemGSTGroup_OnModified(FormControl sender, FormControlEventArgs e)
{
    FormCheckBoxControl  METFollowTransItemGSTGroup = sender as FormCheckBoxControl;

    FormRun formRun = METFollowTransItemGSTGroup.formRun();
    FormStringControl frmCtl = formRun.design().controlName(formControlStr(TAMRebatePosting, Rebate_TaxItemGroup));

    if (METFollowTransItemGSTGroup.checked())
    {
        METTAMRebatePostingFormEventHandler::enableOrDisableTaxItemGroup(frmCtl, false);
    }
    else
    {
        METTAMRebatePostingFormEventHandler::enableOrDisableTaxItemGroup(frmCtl, true);
    }   
}

/// CB201_RebatesExtension_GSTchanges
/// <summary>
/// TAMRebatePosting On selection changed
/// </summary>
/// <param name="sender"> Get form data scontrol object</param>
/// <param name="e">Get form control event args</param>
[FormDataSourceEventHandler(formDataSourceStr(TAMRebatePosting, TAMRebatePosting), FormDataSourceEventType::SelectionChanged),
    SuppressBPWarningAttribute("BPParameterNotUsed", "@MET:BPParameterNotUsedMessage")]
public static void TAMRebatePosting_OnSelectionChanged(FormDataSource sender, FormDataSourceEventArgs e)
{
    TAMRebatePosting rebatePosting = sender.cursor();

    FormStringControl frmCtl = sender.formRun().design().controlName(formControlStr(TAMRebatePosting, Rebate_TaxItemGroup));

    if (rebatePosting && rebatePosting.METFollowTransItemGSTGroup == NoYes::Yes)
    {
        METTAMRebatePostingFormEventHandler::enableOrDisableTaxItemGroup(frmCtl, false);

    }
    else
    {
        METTAMRebatePostingFormEventHandler::enableOrDisableTaxItemGroup(frmCtl, true);
    }
}

/// <summary>
/// enable or disable the string control based on the parameters
/// </summary>
/// <param name = "_formStringControl">TaxItemGroup form string control</param>
/// <param name = "_enable">boolean true or false</param>
private static void enableOrDisableTaxItemGroup(FormStringControl _formStringControl, boolean _enable)
{
    if (_enable)
    {
        _formStringControl.enabled(_enable);
    }
    else
    {
        _formStringControl.text('');
        _formStringControl.enabled(_enable);
    }
}
